package io.arkansas.universalphone.brainllm

class NeuralGraph { private val nodes = linkedMapOf<String, NeuralNode>(); private val synapses = linkedMapOf<String, NeuralSynapse>(); fun addNode(n: NeuralNode): Result<Unit> { if (nodes.containsKey(n.id)) return Result.failure(IllegalArgumentException("Duplicate node: ${n.id}")); nodes[n.id] = n; return Result.success(Unit) }; fun addSynapse(s: NeuralSynapse): Result<Unit> { if (!nodes.containsKey(s.sourceId) || !nodes.containsKey(s.targetId)) return Result.failure(IllegalArgumentException("Synapse endpoints must exist")); if (synapses.containsKey(s.id)) return Result.failure(IllegalArgumentException("Duplicate synapse: ${s.id}")); synapses[s.id] = s; return Result.success(Unit) }; fun node(id: String): NeuralNode? = nodes[id]; fun nodes(): List<NeuralNode> = nodes.values.toList(); fun synapses(): List<NeuralSynapse> = synapses.values.toList(); fun outgoing(id: String) = synapses.values.filter { it.sourceId == id && it.enabled }; fun incoming(id: String) = synapses.values.filter { it.targetId == id && it.enabled }; fun activate(id: String, input: Double): Double { val n = nodes[id] ?: return 0.0; val a = if (input + n.bias >= n.threshold) 1.0 else 0.0; nodes[id] = n.copy(activation = a); return a }; fun propagate(id: String, input: Double): List<NeuralSignal> { activate(id, input); val n = nodes[id] ?: return emptyList(); val now = System.currentTimeMillis(); return outgoing(id).map { NeuralSignal(n.id, it.targetId, n.activation * it.weight, now) } } }
